<?php $id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.active=1");require __DIR__.'/includes/header.php';$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);echo '<section class="pagehead"><h1>Produk tidak ditemukan</h1></section>';require __DIR__.'/includes/footer.php';exit;}$ims=$pdo->prepare('SELECT image FROM product_images WHERE product_id=? ORDER BY sort_order,id');$ims->execute([$id]);$photos=$ims->fetchAll();if(!$photos&&$p['image'])$photos=[['image'=>$p['image']]];?>
<section class="detail product-detail">
<div class="product-gallery">
 <?php foreach($photos as $i=>$ph):?><img class="product-gallery-slide <?=$i?'':'active'?>" src="<?=e($ph['image'])?>" alt="<?=e($p['name'])?>" loading="<?=$i?'lazy':'eager'?>"><?php endforeach;?>
 <?php if(count($photos)>1):?><button class="gallery-arrow gallery-prev" type="button" aria-label="Foto sebelumnya">&#8592;</button><button class="gallery-arrow gallery-next" type="button" aria-label="Foto berikutnya">&#8594;</button><div class="gallery-dots"><?php foreach($photos as $i=>$ph):?><button type="button" class="gallery-dot <?=$i?'':'active'?>" data-index="<?=$i?>" aria-label="Foto <?=$i+1?>"></button><?php endforeach;?></div><?php endif;?>
</div>
<div><small><?=e($p['category_name'])?></small><h1><?=e($p['name'])?></h1><?php if($p['description']):?><p><?=nl2br(e($p['description']))?></p><?php endif;if($p['price']!==''):?><h3><?=e($p['price'])?></h3><?php endif;?><a class="btn btn-dark" href="<?=e(wa('Halo Animo Label, saya tertarik dengan produk '.$p['name']))?>">Konsultasi Produk</a></div></section><?php require __DIR__.'/includes/footer.php';?>